/*
 * Re‑implementation of prog56_kruskal_mst.c – reproduces the observable
 * behaviour of the original obfuscated binary.
 *
 * The program expects a single command‑line argument: the number of edges
 * (m).  If the argument is missing, not a positive integer, or the value is
 * negative, the program prints "INVALID_ARGS" and exits.
 *
 * The value m is capped at 9 (the original source used static arrays of size
 * 9).  Then m lines are read from stdin, each containing three integers
 * "a b w" – the two vertex indices (0‑5) and the edge weight.
 *
 * The program runs Kruskal's algorithm on a graph with six vertices (0‑5).
 * It sorts the edges by increasing weight, adds an edge to the MST when its
 * endpoints belong to different components, and records the selected edges
 * and the total weight.
 *
 * If fewer than 5 edges are selected, the graph is disconnected and the
 * program prints "DISCONNECTED".  Otherwise it prints the total weight and
 * the list of edges in the order they were selected, using the exact format
 * of the original binary:
 *
 *   weight=%d edges=a0-b0,a1-b1,...,a4-b4\n
 * A final newline is printed after the list.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_EDGES 9
#define VERTICES 6
#define MST_SIZE (VERTICES - 1)

typedef struct {
    int a, b;
    int w;
} Edge;

/* ---------- Union‑Find (Disjoint Set) ---------- */
static int parent[VERTICES];

static void uf_init(void) {
    for (int i = 0; i < VERTICES; ++i) {
        parent[i] = i;
    }
}

static int uf_find(int x) {
    if (parent[x] != x) {
        parent[x] = uf_find(parent[x]);
    }
    return parent[x];
}

static void uf_union(int x, int y) {
    int rx = uf_find(x);
    int ry = uf_find(y);
    if (rx != ry) {
        parent[ry] = rx;
    }
}

/* Comparator for qsort – ascending weight, stable for equal weights */
static int edge_cmp(const void *p1, const void *p2) {
    const Edge *e1 = (const Edge *)p1;
    const Edge *e2 = (const Edge *)p2;
    if (e1->w < e2->w) return -1;
    if (e1->w > e2->w) return 1;
    /* keep original order for equal weights */
    return 0;
}

int main(int argc, char **argv) {
    /* ----- argument handling ----- */
    if (argc < 2) {
        puts("INVALID_ARGS");
        return 0;
    }

    char *endptr;
    long m_long = strtol(argv[1], &endptr, 10);
    if (*endptr != '\0' || m_long < 0) {
        puts("INVALID_ARGS");
        return 0;
    }

    int m = (int)m_long;
    if (m > MAX_EDGES) {
        m = MAX_EDGES;               /* cap to the static array size */
    }

    /* ----- read edges ----- */
    Edge edges[MAX_EDGES];
    for (int i = 0; i < m; ++i) {
        if (scanf("%d %d %d", &edges[i].a, &edges[i].b, &edges[i].w) != 3) {
            puts("INVALID_ARGS");
            return 0;
        }
        /* The original program assumed vertices are in 0..5.  Guard against
           out‑of‑range values to avoid undefined behaviour. */
        if (edges[i].a < 0 || edges[i].a >= VERTICES ||
            edges[i].b < 0 || edges[i].b >= VERTICES) {
            puts("INVALID_ARGS");
            return 0;
        }
    }

    /* ----- Kruskal's algorithm ----- */
    qsort(edges, m, sizeof(Edge), edge_cmp);

    uf_init();
    int mst_a[MST_SIZE];
    int mst_b[MST_SIZE];
    int mst_weight = 0;
    int mst_cnt = 0;

    for (int i = 0; i < m && mst_cnt < MST_SIZE; ++i) {
        int u = edges[i].a;
        int v = edges[i].b;
        if (uf_find(u) != uf_find(v)) {
            uf_union(u, v);
            mst_a[mst_cnt] = u;
            mst_b[mst_cnt] = v;
            mst_weight += edges[i].w;
            ++mst_cnt;
        }
    }

    if (mst_cnt != MST_SIZE) {
        puts("DISCONNECTED");
        return 0;
    }

    printf("weight=%d edges=", mst_weight);
    for (int i = 0; i < mst_cnt; ++i) {
        if (i) putchar(',');
        printf("%d-%d", mst_a[i], mst_b[i]);
    }
    putchar('\n');
    return 0;
}
